// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/// @title EmailNotificationService
/// @notice On-chain email template registry with off-chain relay integration
contract EmailNotificationService is Ownable {
    using Strings for uint256;

    struct EmailTemplate {
        string subject;
        string bodyHtml;
        address creator;
        uint256 createdAt;
        bool approved;
    }

    struct PendingEmail {
        uint256 templateId;
        address recipient;
        string[] dynamicFields;
        uint256 scheduledAt;
        bool sent;
    }

    mapping(uint256 => EmailTemplate) public templates;
    mapping(uint256 => PendingEmail) public pendingEmails;
    mapping(address => bool) public approvedSenders;

    uint256 public templateCount;
    uint256 public emailCount;

    // Content security policy for HTML templates
    string constant CSP_HEADER = "default-src 'self'; script-src 'none';";

    // Allowed HTML tags after sanitization
    bytes32 constant SAFE_TAG_HASH_P = keccak256("p");
    bytes32 constant SAFE_TAG_HASH_BR = keccak256("br");
    bytes32 constant SAFE_TAG_HASH_B = keccak256("b");
    bytes32 constant SAFE_TAG_HASH_I = keccak256("i");
    bytes32 constant SAFE_TAG_HASH_SPAN = keccak256("span");
    bytes32 constant SAFE_TAG_HASH_DIV = keccak256("div");

    event EmailQueued(uint256 indexed emailId, address indexed recipient, uint256 templateId);
    event TemplateCreated(uint256 indexed templateId, address indexed creator);
    event EmailRelayed(uint256 indexed emailId, string renderedBody);

    modifier onlyApprovedSender() {
        require(approvedSenders[msg.sender] || msg.sender == owner(), "Not approved");
        _;
    }

    constructor() Ownable(msg.sender) {
        approvedSenders[msg.sender] = true;
    }

    function approveSender(address sender) external onlyOwner {
        approvedSenders[sender] = true;
    }

    /// @notice Register a new email template with HTML body
    /// @dev Body is sanitized through _sanitizeHtml before storage
    function createTemplate(string calldata subject, string calldata bodyHtml) 
        external onlyApprovedSender returns (uint256) 
    {
        uint256 id = templateCount++;
        string memory sanitizedBody = _sanitizeHtml(bodyHtml);

        templates[id] = EmailTemplate({
            subject: subject,
            bodyHtml: sanitizedBody,
            creator: msg.sender,
            createdAt: block.timestamp,
            approved: false
        });

        emit TemplateCreated(id, msg.sender);
        return id;
    }

    /// @notice Admin approves a template for use
    function approveTemplate(uint256 templateId) external onlyOwner {
        require(templateId < templateCount, "Invalid template");
        templates[templateId].approved = true;
    }

    /// @notice Queue an email for async relay
    function queueEmail(
        uint256 templateId, 
        address recipient, 
        string[] calldata dynamicFields
    ) external onlyApprovedSender returns (uint256) {
        require(templateId < templateCount, "Invalid template");
        require(templates[templateId].approved, "Template not approved");

        uint256 emailId = emailCount++;
        pendingEmails[emailId] = PendingEmail({
            templateId: templateId,
            recipient: recipient,
            dynamicFields: dynamicFields,
            scheduledAt: block.timestamp,
            sent: false
        });

        emit EmailQueued(emailId, recipient, templateId);
        return emailId;
    }

    /// @notice Relay processes pending email - renders template with dynamic fields
    /// @dev Called by off-chain relay service to get rendered HTML
    function processEmail(uint256 emailId) external onlyApprovedSender returns (string memory) {
        require(emailId < emailCount, "Invalid email");
        require(!pendingEmails[emailId].sent, "Already sent");

        PendingEmail storage email = pendingEmails[emailId];
        EmailTemplate storage tmpl = templates[email.templateId];

        // Render template with dynamic field substitution
        string memory rendered = _renderTemplate(tmpl.bodyHtml, email.dynamicFields);

        email.sent = true;
        emit EmailRelayed(emailId, rendered);
        return rendered;
    }

    /// @notice Renders template by substituting {{0}}, {{1}}, etc. with dynamic fields
    /// @dev Dynamic fields are sanitized at render time
    function _renderTemplate(string memory template, string[] memory fields) 
        internal pure returns (string memory) 
    {
        string memory result = template;
        for (uint256 i = 0; i < fields.length; i++) {
            string memory placeholder = string(abi.encodePacked("{{", i.toString(), "}}"));
            // Fields are inserted with full HTML sanitization applied
            string memory safeField = _sanitizeHtml(fields[i]);
            result = _replace(result, placeholder, safeField);
        }
        return result;
    }

    /// @notice HTML sanitizer - removes dangerous tags and attributes
    function _sanitizeHtml(string memory input) internal pure returns (string memory) {
        bytes memory inputBytes = bytes(input);
        bytes memory output = new bytes(inputBytes.length * 2);
        uint256 outputLen = 0;

        uint256 i = 0;
        while (i < inputBytes.length) {
            if (inputBytes[i] == '<') {
                // Parse tag name
                uint256 tagStart = i + 1;
                bool isClosing = false;

                if (tagStart < inputBytes.length && inputBytes[tagStart] == '/') {
                    isClosing = true;
                    tagStart++;
                }

                uint256 tagEnd = tagStart;
                while (tagEnd < inputBytes.length && 
                       inputBytes[tagEnd] != '>' && 
                       inputBytes[tagEnd] != ' ' &&
                       inputBytes[tagEnd] != '/') {
                    tagEnd++;
                }

                bytes memory tagName = _slice(inputBytes, tagStart, tagEnd);
                bytes32 tagHash = keccak256(tagName);

                if (_isSafeTag(tagHash)) {
                    // Copy the safe tag but strip all attributes
                    if (isClosing) {
                        output[outputLen++] = '<';
                        output[outputLen++] = '/';
                    } else {
                        output[outputLen++] = '<';
                    }
                    for (uint256 j = 0; j < tagName.length; j++) {
                        output[outputLen++] = tagName[j];
                    }
                    output[outputLen++] = '>';

                    // Skip to end of original tag
                    while (i < inputBytes.length && inputBytes[i] != '>') {
                        i++;
                    }
                    i++; // skip '>'
                } else {
                    // Encode the < as entity and continue
                    output[outputLen++] = '&';
                    output[outputLen++] = 'l';
                    output[outputLen++] = 't';
                    output[outputLen++] = ';';
                    i++;
                }
            } else {
                output[outputLen++] = inputBytes[i];
                i++;
            }
        }

        bytes memory trimmed = _slice(output, 0, outputLen);
        return string(trimmed);
    }

    /// @notice Encode HTML entities in dynamic content
    function _encodeEntities(string memory input) internal pure returns (string memory) {
        bytes memory inputBytes = bytes(input);
        // Allocate generous buffer
        bytes memory output = new bytes(inputBytes.length * 6);
        uint256 outputLen = 0;

        for (uint256 i = 0; i < inputBytes.length; i++) {
            bytes1 c = inputBytes[i];
            if (c == '<') {
                output[outputLen++] = '&'; output[outputLen++] = 'l';
                output[outputLen++] = 't'; output[outputLen++] = ';';
            } else if (c == '>') {
                output[outputLen++] = '&'; output[outputLen++] = 'g';
                output[outputLen++] = 't'; output[outputLen++] = ';';
            } else if (c == '&') {
                output[outputLen++] = '&'; output[outputLen++] = 'a';
                output[outputLen++] = 'm'; output[outputLen++] = 'p';
                output[outputLen++] = ';';
            } else if (c == '"') {
                output[outputLen++] = '&'; output[outputLen++] = 'q';
                output[outputLen++] = 'u'; output[outputLen++] = 'o';
                output[outputLen++] = 't'; output[outputLen++] = ';';
            } else {
                output[outputLen++] = c;
            }
        }

        return string(_slice(output, 0, outputLen));
    }

    function _isSafeTag(bytes32 tagHash) internal pure returns (bool) {
        return tagHash == SAFE_TAG_HASH_P ||
               tagHash == SAFE_TAG_HASH_BR ||
               tagHash == SAFE_TAG_HASH_B ||
               tagHash == SAFE_TAG_HASH_I ||
               tagHash == SAFE_TAG_HASH_SPAN ||
               tagHash == SAFE_TAG_HASH_DIV;
    }

    function _slice(bytes memory data, uint256 start, uint256 end) 
        internal pure returns (bytes memory) 
    {
        bytes memory result = new bytes(end - start);
        for (uint256 i = start; i < end; i++) {
            result[i - start] = data[i];
        }
        return result;
    }

    /// @notice Simple string replacement (first occurrence)
    function _replace(string memory source, string memory find, string memory replaceWith)
        internal pure returns (string memory)
    {
        bytes memory sourceBytes = bytes(source);
        bytes memory findBytes = bytes(find);
        bytes memory replaceBytes = bytes(replaceWith);

        int256 pos = _indexOf(sourceBytes, findBytes);
        if (pos == -1) return source;

        uint256 upos = uint256(pos);
        bytes memory result = new bytes(
            sourceBytes.length - findBytes.length + replaceBytes.length
        );

        uint256 idx = 0;
        for (uint256 i = 0; i < upos; i++) {
            result[idx++] = sourceBytes[i];
        }
        for (uint256 i = 0; i < replaceBytes.length; i++) {
            result[idx++] = replaceBytes[i];
        }
        for (uint256 i = upos + findBytes.length; i < sourceBytes.length; i++) {
            result[idx++] = sourceBytes[i];
        }

        return string(result);
    }

    function _indexOf(bytes memory source, bytes memory find) 
        internal pure returns (int256) 
    {
        if (find.length > source.length) return -1;
        for (uint256 i = 0; i <= source.length - find.length; i++) {
            bool found = true;
            for (uint256 j = 0; j < find.length; j++) {
                if (source[i + j] != find[j]) {
                    found = false;
                    break;
                }
            }
            if (found) return int256(i);
        }
        return -1;
    }
}

